import { h } from "@stencil/core";

export interface FormControlGroupProps {
	labelId?: string;

	label?: string;

	/** Whether or not a label slot has been provided. */
	hasLabelSlot?: boolean;

	/** The help text id, used to map the children elements to the help text */
	helpTextId?: string;

	/** The help text (if the help-text slot isn't used) */
	helpText?: string;

	/** Whether or not a help text slot has been provided. */
	hasHelpTextSlot?: boolean;

	hasFrontSlot?: boolean;
	hasRearSlot?: boolean;

	/** role of group element. */
	role?: string;

	size: "xsmall" | "small" | "medium" | "large";

	/** Element has error state */
	hasError?: boolean;

	/** hide Fieldset  */
	noFieldset?: boolean;

	/** Element is disabled */
	isDisabled?: boolean;

	/** Element is required */
	isRequired?: boolean;

	/** group direction */
	direction?: "row" | "column";

	/** for Radio Group */
	errorMessage?: string;
}

const FormControlGroup = (props: FormControlGroupProps, children) => {
	const hasLabel = !!props.label || props.hasLabelSlot;
	const hasHelpText = !!props.helpText || props.hasHelpTextSlot;
	const helpId = props.helpTextId || "help-text";
	const groupLabelId = props.labelId;
	const hasFront = props.hasFrontSlot;
	const hasRear = props.hasRearSlot;

	return (
		<fieldset
			part="base"
			class={{
				"form-control-group": true,
				"form-control-group--label": hasLabel,
				"form-control-group--hide-label": !hasLabel,
				"form-control-group--hide-fieldset": props.noFieldset,
				"form-control-group--error": props.hasError,
				"form-control-group--xsmall": props.size === "xsmall",
				"form-control-group--small": props.size === "small",
				"form-control-group--medium": props.size === "medium",
				"form-control-group--large": props.size === "large",
				"form-control-group--has-help-text": hasHelpText,
				"form-control-group--disabled": props.isDisabled,
				"form-control-group--has-front": hasFront,
				"form-control-group--has-rear": hasRear,
			}}
			aria-required={props.isRequired ? "true" : "false"}
			aria-labelledby={groupLabelId}
			aria-describedby={helpId}
			role={props.role}
		>
			<div
				part="label"
				class="form-control-group__label"
				aria-hidden={hasLabel ? "false" : "true"}
			>
				<legend
					id={groupLabelId}
					part="legend"
					class="form-control-group__label-legend"
				>
					<slot name="label">{props.label}</slot>
					{props.isRequired && (
						<span
							aria-hidden="true"
							part="asterisk"
							class="form-control-group__label-asterisk"
						>
							*
						</span>
					)}
				</legend>
				<slot name="label-suffix" />
			</div>
			<div part="front" data-testid="front" class="form-control__front">
				<slot name="front" />
			</div>
			<div
				part="children"
				class={{
					"form-control-group__children": true,
					"form-control-group__direction-row": props.direction === "row",
					"form-control-group__direction-column": props.direction === "column",
				}}
			>
				<div class="visually-hidden">
					<div id="error-message" aria-live="assertive">
						{props.errorMessage}
					</div>
					<label class="radio-group__validation">
						<input
							type="text"
							class="radio-group__validation-input"
							required={props.isRequired}
							tabindex="-1"
							hidden
						/>
					</label>
				</div>
				{children}
			</div>
			<div part="rear" data-testid="rear" class="form-control__rear">
				<slot name="rear" />
			</div>
			<div
				part="help-text"
				id={helpId}
				aria-hidden={hasHelpText ? "false" : "true"}
				class={{ "form-control-group__help-text": hasHelpText }}
			>
				<slot name="help-text">{props.helpText}</slot>
			</div>
		</fieldset>
	);
};

export default FormControlGroup;
